var e=[{id:"jeune",title:"Je suis jeune (12-18 ans)",description:"Tu as entre 12 et 18 ans et tu veux vivre un temps fort de rencontres, de pri\xE8re et de f\xEAte ? Alegria est fait pour toi.",ctaLabel:"Voir l\u2019inscription jeunes",ctaLink:"/inscription/jeunes"},{id:"famille",title:"Je deviens famille d\u2019accueil",description:"Proposez un h\xE9bergement pour les jeunes du rassemblement. La coordination vous accompagne et organise les affectations dans les familles.",ctaLabel:"Proposer un accueil",ctaLink:"/inscription/familles"},{id:"animateur",title:"Je suis animateur",description:"Vous accompagnez un groupe de jeunes \xE0 l'ann\xE9e ? Retrouvez comment pr\xE9parer et vivre Alegria avec votre \xE9quipe.",ctaLabel:"D\xE9couvrir mon r\xF4le",ctaLink:"/evenement"},{id:"benevole",title:"Je deviens b\xE9n\xE9vole ou volontaire",description:"Donnez de votre temps avant ou pendant le rassemblement pour que cette aventure collective soit possible.",ctaLabel:"Voir l\u2019inscription b\xE9n\xE9voles",ctaLink:"/inscription/benevoles"},{id:"responsable",title:"Je suis responsable dioc\xE9sain",description:"Vous accompagnez plusieurs groupes de votre dioc\xE8se ? Retrouvez les informations utiles pour coordonner leur venue.",ctaLabel:"Voir la page Contact",ctaLink:"/contact"},{id:"decouverte",title:"Je d\xE9couvre le MEJ",description:"Vous ne connaissez pas encore le MEJ mais vous \xEAtes curieux de vivre cette exp\xE9rience ? Vous \xEAtes les bienvenus, Alegria est ouvert \xE0 tous.",ctaLabel:"D\xE9couvrir l\u2019\xE9v\xE9nement",ctaLink:"/evenement"}],i=[{title:"Je propose un accueil",description:"Je renseigne mes coordonn\xE9es, mes capacit\xE9s et mes contraintes d\u2019h\xE9bergement."},{title:"J\u2019\xE9change avec la coordination",description:"Nous pr\xE9cisons ensemble les possibilit\xE9s et les modalit\xE9s d\u2019accueil."},{title:"La coordination valide ma proposition",description:"L\u2019\xE9quipe confirme les conditions de l\u2019accueil avec moi."},{title:"L\u2019\xE9quipe affecte les jeunes",description:"La coordination organise la r\xE9partition des jeunes dans les familles."},{title:"Je pr\xE9pare l\u2019accueil",description:"Je pr\xE9pare l\u2019arriv\xE9e des jeunes avec les informations transmises par l\u2019\xE9quipe."}],t=[{title:"Rencontre",description:"Se rencontrer entre jeunes venus de toute la France et du Christ."},{title:"Confiance",description:"Vivre une exp\xE9rience collective encadr\xE9e et s\xE9curis\xE9e."},{title:"Joie",description:"C\xE9l\xE9brer, danser, rire et partager des moments de f\xEAte."},{title:"Engagement",description:"S\u2019engager pour soi, pour les autres et pour le monde."},{title:"Fraternit\xE9",description:"Vivre en \xE9quipe, s\u2019entraider et grandir ensemble."},{title:"Ouverture",description:"Accueillir toutes celles et ceux qui d\xE9couvrent le MEJ."},{title:"Foi",description:"Vivre des temps spirituels accessibles \xE0 tous, croyants ou en recherche."}],n=[{value:"4 jours",label:"de rassemblement national"},{value:"Toute la France",label:"de jeunes et dioc\xE8ses repr\xE9sent\xE9s"},{value:"3 encadrants",label:"animateurs, b\xE9n\xE9voles et volontaires mobilis\xE9s"}],s={text:"Croire en ce monde tel qu\u2019il est, avec ses joies et ses difficult\xE9s, parce que nous croyons que Dieu y est \xE0 l\u2019\u0153uvre, ici et maintenant.",attribution:"Esprit des rassemblements Alegria du MEJ"};export{e as a,i as b,t as c,n as d,s as e};
